def dump_msgs(f, maxchars=8000):
 rec=[json.loads(x) for x in f.read_text().splitlines()]
 print('\nFILE',f.name, 'records',len(rec))
 for i,d in enumerate(rec):
  if d.get('type')!='message': continue
  m=d['message']; role=m.get('role'); cont=m.get('content',[])
  if role=='assistant':
   vals=[]
   for item in cont:
    t=item.get('type')
    if t=='text': vals.append(item.get('text',''))
    elif t=='toolCall': vals.append(f"[tool:{item.get('name')} args={str(item.get('arguments'))[:700]}]")
    elif t=='thinking':
     s=item.get('thinking','')
     if s: vals.append('[think] '+s[:500])
   out='\n'.join(vals)
   if out: print(f'\n#{i} ASSISTANT\n{out[:maxchars]}')
  elif role=='user':
   txt='\n'.join(item.get('text','') for item in cont if item.get('type')=='text')
   # extract meaningful line first + output demo headers/actions
   print(f'\n#{i} USER\n{txt[:maxchars]}')

